 int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}boolean landscape(){return getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE;}boolean tablet(){return getResources().getConfiguration().screenWidthDp>=700;}boolean compact(){return landscape()&&!tablet();}TextView text(String s,int size,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.rgb(10,39,75));if(bold)v.setTypeface(null,1);v.setPadding(0,dp(compact()?2:5),0,dp(compact()?2:5));return v;}LinearLayout.LayoutParams margins(int top,int bottom){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(compact()?Math.min(top,6):top),0,dp(compact()?Math.min(bottom,6):bottom));return p;}
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("reka",MODE_PRIVATE);if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);String deviceMode=prefs.getString("device_mode","");if("kiosk".equals(deviceMode)&&!prefs.getString("server","").isEmpty())showKiosk();else if(prefs.contains("token")){QueueService.start(this);showMain();}else if(prefs.getBoolean("server_connected",false)&&!prefs.getString("server","").isEmpty())showModeChoice();else showServerWizard();}
 protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==41&&resultCode==RESULT_OK&&data!=null&&data.getData()!=null){selectedAudioUri=data.getData();try{getContentResolver().takePersistableUriPermission(selectedAudioUri,data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}customAudioStatus.setText("Mengunggah audio…");uploadCustomAudio(selectedAudioUri);}}
