 void baseScreen(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(239,245,251));root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);int pad=compact()?10:(landscape()?18:22),top=compact()?6:(landscape()?12:28);root.setPadding(dp(pad),dp(top),dp(pad),dp(top));scroll.addView(root);LinearLayout brand=new LinearLayout(this);brand.setGravity(Gravity.CENTER_VERTICAL);TextView mark=text("RQ",compact()?15:20,true);mark.setTextColor(Color.rgb(7,59,92));mark.setGravity(17);mark.setBackgroundColor(Color.rgb(255,210,63));int markSize=compact()?36:52;brand.addView(mark,new LinearLayout.LayoutParams(dp(markSize),dp(markSize)));TextView title=text("  Reka Queue Client",compact()?18:23,true);brand.addView(title);root.addView(brand);setContentView(scroll);}
