 void showKiosk(){getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);applyKioskFullscreen();kioskWeb=new WebView(this);kioskWeb.setBackgroundColor(Color.rgb(239,245,251));WebSettings settings=kioskWeb.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setMediaPlaybackRequiresUserGesture(false);settings.setLoadWithOverviewMode(true);settings.setUseWideViewPort(true);kioskWeb.setWebViewClient(new WebViewClient());kioskWeb.loadUrl(prefs.getString("server","")+"/kiosk");kioskWeb.setOnLongClickListener(new View.OnLongClickListener(){public boolean onLongClick(View v){showKioskExit();return true;}});setContentView(kioskWeb);}
