 void showKioskExit(){new AlertDialog.Builder(this).setTitle("Pengaturan kiosk").setMessage("Server tetap akan diingat. Kembali ke pilihan Operator atau Kiosk?").setNegativeButton("Tetap di kiosk",null).setNeutralButton("Disconnect",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){disconnectServer();}}).setPositiveButton("Pilih mode",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){prefs.edit().remove("device_mode").apply();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);showModeChoice();}}).show();}
