 LinearLayout panel(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);int h=compact()?10:(landscape()?18:20),v=compact()?7:(landscape()?14:18);p.setPadding(dp(h),dp(v),dp(h),dp(v));p.setBackgroundResource(R.drawable.panel);return p;}void flat(Button b,int color){GradientDrawable bg=new GradientDrawable();bg.setColor(color);bg.setCornerRadius(dp(9));b.setBackground(bg);b.setTextColor(Color.WHITE);b.setTypeface(null,1);b.setStateListAnimator(null);}EditText field(LinearLayout p,String label,String value,int type){p.addView(text(label,14,true));EditText e=new EditText(this);e.setText(value);e.setTextSize(16);e.setSingleLine(true);e.setInputType(type);e.setTextColor(Color.rgb(10,39,75));e.setPadding(dp(14),0,dp(14),0);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(9));bg.setStroke(dp(1),Color.rgb(190,207,225));e.setBackground(bg);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,dp(54));ep.setMargins(0,dp(5),0,dp(12));p.addView(e,ep);return e;}Button primary(String label){Button b=new Button(this);b.setText(label);b.setTextSize(14);flat(b,Color.rgb(20,120,200));return b;}
